import numpy as np
import os

try:
    from scipy.optimize import linprog
    SCIPY_AVAILABLE = True
except Exception:
    SCIPY_AVAILABLE = False

# ---------------- LP and helpers ----------------

def _boundary_margins(C: np.ndarray) -> np.ndarray:
    x = C[:, 0]; y = C[:, 1]
    return np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))

def _solve_lp_for_radii(C: np.ndarray):
    n = C.shape[0]
    if n != 32 or C.shape != (32, 2):
        return None, 0.0, False
    b = _boundary_margins(C)

    if not SCIPY_AVAILABLE:
        # Conservative fallback: cap at boundary margin and a small constant to avoid overlaps
        r = np.minimum(b, 1.0 / 12.0) * 0.999
        return r, float(np.sum(r)), True

    # Pairwise constraints r_i + r_j <= ||c_i - c_j||
    I = []
    J = []
    for i in range(n):
        for j in range(i + 1, n):
            I.append(i); J.append(j)
    I = np.array(I, dtype=int)
    J = np.array(J, dtype=int)
    D = np.linalg.norm(C[I] - C[J], axis=1)

    m = len(I)
    A_ub = np.zeros((m, n), dtype=float)
    A_ub[np.arange(m), I] = 1.0
    A_ub[np.arange(m), J] = 1.0
    b_ub = D

    c = -np.ones(n, dtype=float)
    bounds = [(0.0, float(max(0.0, bi))) for bi in b]

    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not hasattr(res, "success") or not res.success:
        return None, 0.0, False
    r = res.x.astype(float)
    return r, float(-res.fun), True

def _safety_shrink(C: np.ndarray, r: np.ndarray, factor: float = 0.999):
    r2 = r.astype(float).copy()
    r2 *= factor
    r2 = np.minimum(r2, _boundary_margins(C))
    r2 = np.maximum(r2, 1e-12)
    return r2

def _validate(C: np.ndarray, r: np.ndarray) -> bool:
    if C.shape != (32, 2) or r.shape != (32,):
        return False
    if np.any(~np.isfinite(C)) or np.any(~np.isfinite(r)) or np.any(r <= 0):
        return False
    x = C[:, 0]; y = C[:, 1]
    if np.any(x - r < 0) or np.any(x + r > 1) or np.any(y - r < 0) or np.any(y + r > 1):
        return False
    # Check pairwise non-overlap
    diff = C[:, None, :] - C[None, :, :]
    D = np.sqrt(np.sum(diff * diff, axis=-1))
    R = r[:, None] + r[None, :]
    iu = np.triu_indices(32, 1)
    if np.any(D[iu] < R[iu] - 1e-12):
        return False
    return True

# ---------------- Baselines and layout constructors ----------------

def _baseline_grid_6x6_minus_corners():
    s = 1.0 / 6.0
    r0 = 0.5 * s
    xs = r0 + s * np.arange(6, dtype=float)
    ys = r0 + s * np.arange(6, dtype=float)
    centers = []
    for i in range(6):
        for j in range(6):
            if (i == 0 and j == 0) or (i == 0 and j == 5) or (i == 5 and j == 0) or (i == 5 and j == 5):
                continue
            centers.append([xs[j], ys[i]])
    C = np.array(centers, dtype=float)
    r = np.full(32, r0 * (1.0 - 1e-12), dtype=float)
    return C, r, float(np.sum(r))

def _rows_y_positions(rows: int, margin: float) -> np.ndarray:
    # evenly spaced between [margin, 1 - margin]
    if rows == 1:
        return np.array([0.5], dtype=float)
    return np.linspace(margin, 1.0 - margin, rows)

def _row_linspace(k: int, margin_x: float) -> np.ndarray:
    # k points between [margin_x, 1 - margin_x]
    if k == 1:
        return np.array([0.5], dtype=float)
    return np.linspace(margin_x, 1.0 - margin_x, k)

def _make_alt_rows(counts, y_margin, m5, m4, delta):
    ys = _rows_y_positions(len(counts), y_margin)
    xs5 = _row_linspace(5, m5)
    xs4 = _row_linspace(4, m4) + delta
    xs4 = np.clip(xs4, 1e-6, 1.0 - 1e-6)
    C = []
    for idx, k in enumerate(counts):
        if k == 5:
            for x in xs5:
                C.append([x, ys[idx]])
        elif k == 4:
            for x in xs4:
                C.append([x, ys[idx]])
        else:
            raise ValueError("counts must contain only 4 or 5")
    C = np.array(C, dtype=float)
    # Might not be exactly 32 if counts mismatched
    return C

# ---------------- Local refinements ----------------

def _micro_jitter_search(C0: np.ndarray, steps: int = 150, sigma: float = 0.008, seed: int = 2025):
    rng = np.random.default_rng(seed)
    C_best = C0.copy()
    r_best, obj_best, ok = _solve_lp_for_radii(C_best)
    if not ok:
        return C0, r_best, obj_best
    for _ in range(steps):
        C_try = C_best.copy()
        i = int(rng.integers(0, C_try.shape[0]))
        d = rng.normal(0.0, sigma, size=2)
        C_try[i] = np.clip(C_try[i] + d, 1e-6, 1.0 - 1e-6)
        r_try, obj_try, ok = _solve_lp_for_radii(C_try)
        if ok and obj_try > obj_best + 1e-12:
            C_best, r_best, obj_best = C_try, r_try, obj_try
    return C_best, r_best, obj_best

# ---------------- Persistence ----------------

SAVE_PATH = 'storage/verity/sumr32_best.npz'

def _load_persisted():
    if os.path.exists(SAVE_PATH):
        try:
            data = np.load(SAVE_PATH)
            C = data['centers'].astype(float)
            r = data['radii'].astype(float)
            if C.shape == (32, 2) and r.shape == (32,):
                return C, r, float(np.sum(r))
        except Exception:
            pass
    return None

def _save_best(C, r):
    try:
        os.makedirs(os.path.dirname(SAVE_PATH), exist_ok=True)
        np.savez(SAVE_PATH, centers=C, radii=r, obj=float(np.sum(r)))
    except Exception:
        pass

# ---------------- Main entry ----------------

def construct_packing() -> tuple:
    n = 32
    # Strong baseline and optional persisted best
    C_base, r_base, obj_base = _baseline_grid_6x6_minus_corners()
    best_C, best_r, best_obj = C_base, r_base, obj_base

    persisted = _load_persisted()
    if persisted is not None:
        Cp, rp, objp = persisted
        # Re-solve LP to ensure constraints tight
        rp2, objp2, okp = _solve_lp_for_radii(Cp)
        if okp:
            rp2 = _safety_shrink(Cp, rp2)
            objp2 = float(np.sum(rp2))
            if objp2 > best_obj + 1e-12:
                best_C, best_r, best_obj = Cp, rp2, objp2

    # Randomized parameter search over alternating 5/4 rows
    rng = np.random.default_rng(314159)
    patterns = [
        [5,4,5,4,5,4,5],        # classic alternating rows (sum=32)
        [4,5,4,5,4,5,5],        # variant (sum=32)
    ]

    top = []  # store (obj, C, r)
    trials = 320
    for _ in range(trials):
        y_margin = float(rng.uniform(0.06, 0.14))
        # margins for x-spaces of 5-rows and 4-rows
        m5 = float(rng.uniform(0.06, 0.14))
        m4 = float(rng.uniform(0.06, 0.14))
        # relative phase/offset for 4-rows
        delta = float(rng.uniform(-0.04, 0.04))

        for counts in patterns:
            C = _make_alt_rows(counts, y_margin, m5, m4, delta)
            if C.shape != (32, 2):
                continue
            r, obj, ok = _solve_lp_for_radii(C)
            if not ok:
                continue
            # Keep top 6
            if len(top) < 6 or obj > top[-1][0] + 1e-12:
                top.append((obj, C, r))
                top.sort(key=lambda t: t[0], reverse=True)
                top = top[:6]

    # Refine top candidates with micro-jitter
    for obj0, C0, r0 in list(top):
        C1, r1, obj1 = _micro_jitter_search(C0, steps=180, sigma=0.007, seed=2026)
        if obj1 > best_obj + 1e-12:
            best_C, best_r, best_obj = C1, r1, obj1

    # Final safety shrink and validation; guarantee non-regression w.r.t. baseline
    best_r = _safety_shrink(best_C, best_r, factor=0.999)
    if not _validate(best_C, best_r) or best_obj < obj_base - 1e-9:
        return C_base, r_base

    # Persist best for future warm-starts
    _save_best(best_C, best_r)
    return best_C, best_r
